TRUNCATE TABLE `article`;
TRUNCATE TABLE `article__category`;
TRUNCATE TABLE `article__column`;
TRUNCATE TABLE `article__tag`;
TRUNCATE TABLE `captcha`;
TRUNCATE TABLE `category`;
TRUNCATE TABLE `column`;
TRUNCATE TABLE `comment`;
TRUNCATE TABLE `diary`;
TRUNCATE TABLE `emoji`;
