-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS`article`;
CREATE TABLE`article`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标题',
    `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图',
    `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容',
    `is_featured` tinyint NULL DEFAULT 0 COMMENT '是否精选 0-否 1-是',
    `excerpt` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '摘要',
    `status` tinyint NULL DEFAULT 0 COMMENT '状态：0-草稿 1-发布 2-归档',
    `view_count` int NULL DEFAULT NULL COMMENT '浏览量',
    `comment_count` int NULL DEFAULT NULL COMMENT '评论量',
    `like_count` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '点赞量',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for article__category
-- ----------------------------
DROP TABLE IF EXISTS`article__category`;
CREATE TABLE`article__category`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `article_id` bigint NOT NULL COMMENT '文章ID',
    `category_id` bigint NOT NULL COMMENT '分类ID',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章-分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for article__column
-- ----------------------------
DROP TABLE IF EXISTS`article__column`;
CREATE TABLE`article__column`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `article_id` bigint NOT NULL COMMENT '文章ID',
    `column_id` bigint NOT NULL COMMENT '专栏ID',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章_专栏' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for article__tag
-- ----------------------------
DROP TABLE IF EXISTS`article__tag`;
CREATE TABLE`article__tag`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `article_id` bigint NOT NULL COMMENT '文章ID',
    `tag_id` bigint NOT NULL COMMENT '标签ID',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '文章-标签' ROW_FORMAT = Dynamic;


-- ----------------------------
-- Table structure for captcha
-- ----------------------------
DROP TABLE IF EXISTS `captcha`;
CREATE TABLE `captcha`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `uuid` varchar(72) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'UUID',
  `code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '验证码',
  `expired_at` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `creator` bigint NULL DEFAULT NULL COMMENT '创建者',
  `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '验证码' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for category
-- ----------------------------
DROP TABLE IF EXISTS`category`;
CREATE TABLE`category`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '名称',
    `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '描述',
    `parent_id` bigint NULL DEFAULT NULL COMMENT '父级ID 0-表示顶级',
    `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '分类' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for column
-- ----------------------------
DROP TABLE IF EXISTS`column`;
CREATE TABLE`column`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '名称',
    `introduction` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '简介',
    `cover` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '封面图',
    `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '专栏' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for comment
-- ----------------------------
DROP TABLE IF EXISTS`comment`;
CREATE TABLE`comment`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `target_id` bigint NULL DEFAULT NULL COMMENT '关联目标ID 文章ID、日记ID 根据type决定是什么ID\r\n留言板不需要 ',
    `content` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '内容',
    `parent_id` bigint NULL DEFAULT 0 COMMENT '父级ID 0-表示顶级',
    `type` int NOT NULL COMMENT '类型: 1-文章 2-日记 3-留言',
    `is_private` tinyint NULL DEFAULT 0 COMMENT '是否私密 0-否 1-是',
    `is_anonymous` tinyint NULL DEFAULT 0 COMMENT '是否匿名 0-否 1-是',
    `status` int NULL DEFAULT NULL COMMENT '状态 0-待审核 1-审核通过 2-审核拒绝',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '评论' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for diary
-- ----------------------------
DROP TABLE IF EXISTS`diary`;
CREATE TABLE`diary`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '标题',
    `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '内容',
    `mood_id` bigint NULL DEFAULT NULL COMMENT '心情ID',
    `weather_id` bigint NULL DEFAULT NULL COMMENT '天气ID',
    `location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '地址',
    `is_private` tinyint NULL DEFAULT 1 COMMENT '是否私密 0-否 1-是',
    `status` tinyint NULL DEFAULT 0 COMMENT '状态：0-草稿 1-发布 2-归档',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '日记' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for emoji
-- ----------------------------
DROP TABLE IF EXISTS`emoji`;
CREATE TABLE`emoji`(
    `id` bigint NOT NULL AUTO_INCREMENT,
    `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '名称',
    `emoji` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'emoji表情',
    `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'emoji表情' ROW_FORMAT = Dynamic;

