-- ----------------------------
-- Table structure for like
-- ----------------------------
DROP TABLE IF EXISTS`like`;
CREATE TABLE`like`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `target_id` bigint NULL DEFAULT NULL COMMENT '关联目标ID 文章ID、日记ID 根据type决定是什么ID\r\n留言板不需要 ',
    `type` int NOT NULL COMMENT '类型: 1-文章 2-日记 3-留言|评论',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '点赞' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of like
-- ----------------------------

-- ----------------------------
-- Table structure for mood
-- ----------------------------
DROP TABLE IF EXISTS`mood`;
CREATE TABLE`mood`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '名称',
    `emoji` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'emoji表情',
    `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '心情' ROW_FORMAT = Dynamic;

