-- ----------------------------
-- Table structure for setting
-- ----------------------------
DROP TABLE IF EXISTS`setting`;
CREATE TABLE`setting`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `code` int NULL DEFAULT NULL COMMENT '配置项编码',
    `value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '配置项值',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NULL DEFAULT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '系统设置表' ROW_FORMAT = Dynamic;

