-- ----------------------------
-- Table structure for tag
-- ----------------------------
DROP TABLE IF EXISTS`tag`;
CREATE TABLE`tag`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '名称',
    `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '标签' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for token
-- ----------------------------
DROP TABLE IF EXISTS `token`;
CREATE TABLE `token`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `access_token` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '凭证',
  `access_expired_at` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `creator` bigint NOT NULL COMMENT '创建者',
  `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Token凭证' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS`user`;
CREATE TABLE`user`(
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '昵称',
    `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '头像',
    `sex` int NULL DEFAULT 2 COMMENT '性别 0-女 1-男 2-未知',
    `email` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '邮箱',
    `qq_open_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'QQopenid',
    `role` int NULL DEFAULT 1 COMMENT '角色：0-作者 1-读者',
    `status` tinyint NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
    `last_at` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '最后在线时间',
    `created_at` datetime NOT NULL COMMENT '创建时间',
    `creator` bigint NOT NULL COMMENT '创建者',
    `updated_at` datetime NULL DEFAULT NULL COMMENT '更新时间',
    `updater` bigint NULL DEFAULT NULL COMMENT '更新者',
    `deleted` tinyint NULL DEFAULT 0 COMMENT '是否删除：0-否 1-是',
    PRIMARY KEY(`id`) USING BTREE
  ) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user
-- ----------------------------
